export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let stepCount = 0;
  let prevPos = null, prevVel = null, prevAtt = null, prevRates = null;
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };

  // Simulator inner attitude integral tracker and motor lag estimates
  const simInt = { roll: 0, pitch: 0 };
  const uLag = { roll: 0, pitch: 0 };
  const biasRatio = { roll: 0, pitch: 0 };
  const biasResid = { roll: 0, pitch: 0 };

  // Specific thrust scale K_T = (maxTotalThrust / mass), hover around ~20.6
  let kT = 20.5;
  let laggedThrust = 0.48;
  let intY = 0;

  // Wind acceleration observers: dragCoeff * wind
  const windFast = { x: 0, z: 0 };
  const windSlow = { x: 0, z: 0 };

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let settle = 0;
  let padPinned = false;

  return {
    step(obs) {
