          intY = clamp(intY + dyGate * dt, -0.15, 0.15);
        } else {
          intY *= 0.92;
        }

        const vxForward = Math.max(0.50, v.x);
        const tCross = clamp(dxGate / vxForward, 0.02, 0.30);
        const zPred = p.z + v.z * tCross + 0.25 * azCur * tCross * tCross;
