        const alphaDes = 62 * (desAngle - att[axis]) - 15.5 * rates[axis] + 0.4 * rates[axis];
        const uTarget = alphaDes - totalBias;
        cmd[axis] = clamp(att[axis] + (uTarget + 13 * rates[axis] - 22 * simInt[axis]) / 65, -0.6, 0.6);
      }

      lastAction = cmd;
      return cmd;
    },
  };
